fn a_staged_update_takes_the_binarys_place() {
    let dir = std::env::temp_dir().join(format!("suspense-self-update-{}", std::process::id()));
    std::fs::remove_dir_all(&dir).ok();
    std::fs::create_dir_all(&dir).unwrap();
